SELECT app_name, SUM(ppl_cnt) AS user_count
FROM {table_name}
GROUP BY app_name
ORDER BY user_count DESC
LIMIT 10;

SELECT
  ROUND(
    100.0 * SUM(CASE WHEN gender = '女' THEN ppl_cnt ELSE 0 END)
    / NULLIF(SUM(CASE WHEN gender IN ('男', '女') THEN ppl_cnt ELSE 0 END), 0),
    2
  ) AS female_percent
FROM {table_name}
WHERE gender IN ('男', '女');
